import type { IGameDataProvider } from '../data/index.js';
import type { BoardToken, Coord, MatchState, Side, UnitTemplate } from '../model/index.js';
import { chebyshev, resolveDamage, templateForMember, tileAt } from '../rules/index.js';

/**
 * Shared scoring helpers for AI policies (GreedyPolicy today, a future MinimaxPolicy
 * tomorrow). Pure + deterministic: scoring never consumes the match RNG, so ranking an
 * action does not perturb the stream the reducer will use to apply it.
 */

// ── AI-METHOD ── regenerated by annotate_methods — do not hand-edit
// @ai-method: tokenHp — (no summary)
// @ai-hash: 40b557b7
// ── END AI-METHOD ──
/** Current hit points of a token (unit hp / squadron hpPool). */
export function tokenHp(token: BoardToken): number {
  return token.kind === 'unit' ? token.hp : token.hpPool;
}

// ── AI-METHOD ── regenerated by annotate_methods — do not hand-edit
// @ai-method: isLiving — (no summary)
// @ai-hash: 7f1305c2
// ── END AI-METHOD ──
/** A token is alive when it still has hit points. */
export function isLiving(token: BoardToken): boolean {
  return tokenHp(token) > 0;
}

// ── AI-METHOD ── regenerated by annotate_methods — do not hand-edit
// @ai-method: templateFor — (no summary)
// @ai-hash: 95112de4
// ── END AI-METHOD ──
/** Resolve a token to a representative UnitTemplate (squadron → its first member). */
export function templateFor(token: BoardToken, provider: IGameDataProvider): UnitTemplate {
  const templateId = token.kind === 'unit' ? token.templateId : token.members[0].templateId;
  return templateForMember(templateId, provider);
}

// ── AI-METHOD ── regenerated by annotate_methods — do not hand-edit
// @ai-method: livingEnemies — (no summary)
// @ai-hash: 288d0793
// ── END AI-METHOD ──
/** Every living enemy token relative to `side`. */
export function livingEnemies(state: MatchState, side: Side): BoardToken[] {
  return state.tokens.filter((t) => t.side !== side && isLiving(t));
}

// ── AI-METHOD ── regenerated by annotate_methods — do not hand-edit
// @ai-method: nearestEnemyDistance — (no summary)
// @ai-hash: 037d8d34
// ── END AI-METHOD ──
/** Chebyshev distance from `from` to the nearest of `enemies` (Infinity if none). */
export function nearestEnemyDistance(from: Coord, enemies: readonly BoardToken[]): number {
  let best = Infinity;
  for (const e of enemies) {
    const d = chebyshev(from, e.pos);
    if (d < best) best = d;
  }
  return best;
}

// ── AI-METHOD ── regenerated by annotate_methods — do not hand-edit
// @ai-method: scoreAttack — (no summary)
// @ai-hash: 6fd82dc8
// ── END AI-METHOD ──
/**
 * Deterministic expected damage of `attackerId` striking `targetId` in the current state
 * (0 if either token is missing). Mirrors what `applyAttack` feeds `resolveDamage`, but
 * WITHOUT an rng so the value is stable for ranking. Terrain, moon phase, and the
 * defender's statuses all factor in, so Greedy scores the real matchup.
 */
export function scoreAttack(
  state: MatchState,
  attackerId: string,
  targetId: string,
  provider: IGameDataProvider,
): number {
  const attacker = state.tokens.find((t) => t.instanceId === attackerId);
  const target = state.tokens.find((t) => t.instanceId === targetId);
  if (!attacker || !target) return 0;
  return resolveDamage({
    attacker: templateFor(attacker, provider),
    defender: templateFor(target, provider),
    defenderTerrainKey: tileAt(state.board, target.pos)?.terrain ?? 'Field',
    moonSky: state.moon.sky,
    attackerAlignment: attacker.kind === 'unit' ? attacker.alignment : undefined,
    defenderStatusKeys: target.statuses.map((s) => s.key),
    provider,
  }).amount;
}
